import{_ as n,c as i,o as r,a2 as t}from"./chunks/framework.PGES7OoM.js";const h=JSON.parse('{"title":"Curvy for Enterprises & Institutions","description":"","frontmatter":{"rawMarkdown":"# Curvy for Enterprises & Institutions\\n\\n> [!NOTE]\\n> To get started with enterprise Curvy integration, [schedule a call with our CEO, Petar](https://curvy.box/petar).\\n\\n## Private payments, branded and controlled\\n\\nCurvy enables enterprises and institutions to deploy privacy-enabled payment infrastructure with full branding, compliance alignment, and operational control.\\n\\nBuilt for organizations that require privacy, regulatory alignment, full customization, and scalable execution.\\n\\n---\\n\\n## Enterprise capabilities\\n\\n### White-label user domains\\n\\nLaunch enterprise-branded programmable identities.\\n\\nExample:\\n\\n`satoshi.yourcompany.io`  \\ninstead of  \\n`satoshi.curvy.name`\\n\\nThis allows you to:\\n\\n- Own the identity layer\\n- Control user namespaces\\n- Align on-chain identity with your brand\\n- Define programmable transaction behavior at the domain level\\n\\n---\\n\\n### White-label application domain\\n\\nDeploy a fully re-branded application interface under your own domain.\\n\\nThis includes:\\n\\n- Custom frontend styling\\n- Enterprise UX adjustments\\n- Integrated workflows\\n- Institutional-grade onboarding logic\\n\\nCurvy infrastructure operates in the background while your brand remains fully visible.\\n\\n---\\n\\n### Custom fee models\\n\\nDefine pricing and settlement logic aligned with your business model.\\n\\nOptions include:\\n\\n- Ecosystem-level fee configuration\\n- Subsidized privacy flows\\n- Revenue sharing structures\\n\\nYou control how value flows through your ecosystem.\\n\\n---\\n\\n### Custom privacy aggregator routing\\n\\nControl where and how funds are aggregated inside the Privacy Aggregator.\\n\\nThis enables:\\n\\n- Dedicated aggregation pools\\n- Jurisdiction-specific routing\\n- Institutional liquidity separation\\n- Controlled exit pathways\\n\\n---\\n\\n### Custom networks and tokens\\n\\nSupport only the chains and assets relevant to your organization.\\n\\n- Restrict allowed networks\\n- Whitelist approved tokens\\n- Define asset-level risk policies\\n- Align infrastructure with internal mandates\\n\\n---\\n\\n### Custom compliance rules\\n\\nCurvy includes a modular compliance framework that can be aligned with your institutional requirements.\\n\\nConfigurable components include:\\n\\n- KYB / KYC integrations\\n- KYT integrations\\n- Risk scoring thresholds\\n- Sanctions screening\\n- Policy-based transaction filtering\\n- Retroactive compliance models\\n- Viewing key frameworks for full audit capability\\n\\n---\\n\\n### 24/7 Enterprise support\\n\\nEnterprise partners receive:\\n\\n- SLA-backed support\\n- Dedicated communication channel\\n- Technical collaboration workflow\\n- Prioritized roadmap alignment\\n- Security response coordination\\n\\n---\\n\\n## Architecture Overview\\n\\nCurvy provides:\\n\\n- Non-custodial smart contract infrastructure\\n- Stealth address-based private receiving\\n- ZK-based Privacy Aggregator for private execution\\n- Compliance-aware Portal Broadcasters\\n- SDK for system-level integration\\n\\nEnterprises can integrate:\\n\\n- Identity layer only\\n- Privacy receiving only\\n- Full shielding and aggregation flows\\n- Or fully customized infrastructure stack\\n\\n---\\n\\n## Designed for Institutional Use Cases\\n\\nCurvy is suitable for:\\n\\n- Payment processors\\n- Regulated exchanges\\n- Fintech platforms\\n- Enterprise treasury operations\\n- Blockchain ecosystems\\n- Institutional DeFi access layers\\n\\n---\\n\\n## Why Curvy for Enterprise?\\n\\n- Non-custodial by design\\n- Privacy and compliance combined\\n- Fully programmable infrastructure\\n- Brand-level control\\n- Multi-chain deployment\\n- Enterprise-grade support model\\n","rawMarkdownPath":"/_raw/for-businesses/for-enterprises-and-institutions.md","rawMarkdownTitle":"Curvy for Enterprises & Institutions","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-businesses/for-enterprises-and-institutions.md"},"headers":[],"relativePath":"for-businesses/for-enterprises-and-institutions.md","filePath":"for-businesses/for-enterprises-and-institutions.md","lastUpdated":1773768298000}'),a={name:"for-businesses/for-enterprises-and-institutions.md"};function o(s,e,l,u,c,d){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="curvy-for-enterprises-institutions" tabindex="-1">Curvy for Enterprises &amp; Institutions <a class="header-anchor" href="#curvy-for-enterprises-institutions" aria-label="Permalink to &quot;Curvy for Enterprises &amp; Institutions&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>To get started with enterprise Curvy integration, <a href="https://curvy.box/petar" target="_blank" rel="noreferrer">schedule a call with our CEO, Petar</a>.</p></div><h2 id="private-payments-branded-and-controlled" tabindex="-1">Private payments, branded and controlled <a class="header-anchor" href="#private-payments-branded-and-controlled" aria-label="Permalink to &quot;Private payments, branded and controlled&quot;">​</a></h2><p>Curvy enables enterprises and institutions to deploy privacy-enabled payment infrastructure with full branding, compliance alignment, and operational control.</p><p>Built for organizations that require privacy, regulatory alignment, full customization, and scalable execution.</p><hr><h2 id="enterprise-capabilities" tabindex="-1">Enterprise capabilities <a class="header-anchor" href="#enterprise-capabilities" aria-label="Permalink to &quot;Enterprise capabilities&quot;">​</a></h2><h3 id="white-label-user-domains" tabindex="-1">White-label user domains <a class="header-anchor" href="#white-label-user-domains" aria-label="Permalink to &quot;White-label user domains&quot;">​</a></h3><p>Launch enterprise-branded programmable identities.</p><p>Example:</p><p><code>satoshi.yourcompany.io</code><br> instead of<br><code>satoshi.curvy.name</code></p><p>This allows you to:</p><ul><li>Own the identity layer</li><li>Control user namespaces</li><li>Align on-chain identity with your brand</li><li>Define programmable transaction behavior at the domain level</li></ul><hr><h3 id="white-label-application-domain" tabindex="-1">White-label application domain <a class="header-anchor" href="#white-label-application-domain" aria-label="Permalink to &quot;White-label application domain&quot;">​</a></h3><p>Deploy a fully re-branded application interface under your own domain.</p><p>This includes:</p><ul><li>Custom frontend styling</li><li>Enterprise UX adjustments</li><li>Integrated workflows</li><li>Institutional-grade onboarding logic</li></ul><p>Curvy infrastructure operates in the background while your brand remains fully visible.</p><hr><h3 id="custom-fee-models" tabindex="-1">Custom fee models <a class="header-anchor" href="#custom-fee-models" aria-label="Permalink to &quot;Custom fee models&quot;">​</a></h3><p>Define pricing and settlement logic aligned with your business model.</p><p>Options include:</p><ul><li>Ecosystem-level fee configuration</li><li>Subsidized privacy flows</li><li>Revenue sharing structures</li></ul><p>You control how value flows through your ecosystem.</p><hr><h3 id="custom-privacy-aggregator-routing" tabindex="-1">Custom privacy aggregator routing <a class="header-anchor" href="#custom-privacy-aggregator-routing" aria-label="Permalink to &quot;Custom privacy aggregator routing&quot;">​</a></h3><p>Control where and how funds are aggregated inside the Privacy Aggregator.</p><p>This enables:</p><ul><li>Dedicated aggregation pools</li><li>Jurisdiction-specific routing</li><li>Institutional liquidity separation</li><li>Controlled exit pathways</li></ul><hr><h3 id="custom-networks-and-tokens" tabindex="-1">Custom networks and tokens <a class="header-anchor" href="#custom-networks-and-tokens" aria-label="Permalink to &quot;Custom networks and tokens&quot;">​</a></h3><p>Support only the chains and assets relevant to your organization.</p><ul><li>Restrict allowed networks</li><li>Whitelist approved tokens</li><li>Define asset-level risk policies</li><li>Align infrastructure with internal mandates</li></ul><hr><h3 id="custom-compliance-rules" tabindex="-1">Custom compliance rules <a class="header-anchor" href="#custom-compliance-rules" aria-label="Permalink to &quot;Custom compliance rules&quot;">​</a></h3><p>Curvy includes a modular compliance framework that can be aligned with your institutional requirements.</p><p>Configurable components include:</p><ul><li>KYB / KYC integrations</li><li>KYT integrations</li><li>Risk scoring thresholds</li><li>Sanctions screening</li><li>Policy-based transaction filtering</li><li>Retroactive compliance models</li><li>Viewing key frameworks for full audit capability</li></ul><hr><h3 id="_24-7-enterprise-support" tabindex="-1">24/7 Enterprise support <a class="header-anchor" href="#_24-7-enterprise-support" aria-label="Permalink to &quot;24/7 Enterprise support&quot;">​</a></h3><p>Enterprise partners receive:</p><ul><li>SLA-backed support</li><li>Dedicated communication channel</li><li>Technical collaboration workflow</li><li>Prioritized roadmap alignment</li><li>Security response coordination</li></ul><hr><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>Curvy provides:</p><ul><li>Non-custodial smart contract infrastructure</li><li>Stealth address-based private receiving</li><li>ZK-based Privacy Aggregator for private execution</li><li>Compliance-aware Portal Broadcasters</li><li>SDK for system-level integration</li></ul><p>Enterprises can integrate:</p><ul><li>Identity layer only</li><li>Privacy receiving only</li><li>Full shielding and aggregation flows</li><li>Or fully customized infrastructure stack</li></ul><hr><h2 id="designed-for-institutional-use-cases" tabindex="-1">Designed for Institutional Use Cases <a class="header-anchor" href="#designed-for-institutional-use-cases" aria-label="Permalink to &quot;Designed for Institutional Use Cases&quot;">​</a></h2><p>Curvy is suitable for:</p><ul><li>Payment processors</li><li>Regulated exchanges</li><li>Fintech platforms</li><li>Enterprise treasury operations</li><li>Blockchain ecosystems</li><li>Institutional DeFi access layers</li></ul><hr><h2 id="why-curvy-for-enterprise" tabindex="-1">Why Curvy for Enterprise? <a class="header-anchor" href="#why-curvy-for-enterprise" aria-label="Permalink to &quot;Why Curvy for Enterprise?&quot;">​</a></h2><ul><li>Non-custodial by design</li><li>Privacy and compliance combined</li><li>Fully programmable infrastructure</li><li>Brand-level control</li><li>Multi-chain deployment</li><li>Enterprise-grade support model</li></ul>',56)])])}const m=n(a,[["render",o]]);export{h as __pageData,m as default};
